{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, approx_quantile(duration/1e6,0.5) p50_ms, approx_quantile(duration/1e6,0.95) p95_ms FROM normal_traces WHERE span_name IN ('geo.Geo/Nearby') GROUP BY 1,2,3 UNION ALL SELECT service_name, span_name, attr_span_kind, COUNT(*), approx_quantile(duration/1e6,0.5), approx_quantile(duration/1e6,0.95) FROM abnormal_traces WHERE span_name IN ('geo.Geo/Nearby') GROUP BY 1,2,3",
          "claim": "search's client span to geo.Geo/Nearby rose from ~0.6 ms to ~2.7 s p95, while geo's own server span stayed ~0.2 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE service_name='geo' GROUP BY 1,2,3",
          "claim": "geo server spans stay at about 0.23 ms p95 during the incident, so the delay is not inside geo.",
          "_note": "geo server p95 unchanged; delay lies on the search->geo connection"
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' src, service_name, metric, COUNT(*) n, AVG(value) avgv FROM abnormal_metrics WHERE service_name IN ('geo','search') AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.rss','k8s.container.restarts','k8s.pod.uptime') GROUP BY 1,2,3 UNION ALL SELECT 'norm', service_name, metric, COUNT(*), AVG(value) FROM normal_metrics WHERE service_name IN ('geo','search') AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.rss','k8s.container.restarts','k8s.pod.uptime') GROUP BY 1,2,3",
          "claim": "geo and search CPU, memory, restarts and uptime are unchanged, so no resource or restart fault on either end."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, approx_quantile(duration/1e6,0.5) p50_ms, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE span_name IN ('geo.Geo/Nearby','search.Search/Nearby') GROUP BY 1,2,3 ORDER BY 1,2,3",
          "claim": "The geo call delay is inherited by search: search.Search/Nearby server p95 rises to about 2.67 s, close to its geo client span."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, approx_quantile(duration/1e6,0.5) p50_ms, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE span_name IN ('search.Search/Nearby','HTTP /hotels') GROUP BY 1,2,3 ORDER BY 1,2,3",
          "claim": "frontend's search.Search/Nearby client span and HTTP /hotels server span both rise to about 2.7 s p95, user-facing latency."
        }
      ]
    }
  ]
}
